mapper.update:
UPDATE user_achievement ua
INNER JOIN app_user u ON u.id = ua.user_id
SET ua.notified_at = CURRENT_TIMESTAMP
WHERE u.username = #{username}
  AND ua.achievement_id = #{achievementId}
  AND ua.notified_at IS NULL

UPDATE user_achievement ua
INNER JOIN app_user u ON u.id = ua.user_id
SET ua.selected = TRUE
WHERE u.username = #{username}
  AND ua.achievement_id = #{achievementId}
